source(file.path(Sys.getenv("W"), "common.R"))
tbl <- lake_open(file.path(W, "t/types"))
sh <- function(label, e) { r <- try1(e); cat(sprintf("%-58s ", label)); if (is_err(r)) cat("ERR", substr(r$msg, 1, 130), "\n") else if (is.data.frame(r)) cat("a:", paste(r$a, collapse = ","), "\n") else cat(format(r), "\n") }
R <- function(...) suppressWarnings(lake_read(tbl, columns = "a", ...))
sh("typo column, no such variable", R(filter = aa > 10))
aa <- 50; sh("typo column 'aa', variable aa <- 50 exists", R(filter = aa > 10))
sh("typo in files()", nrow(lake_files(tbl, filter = aa > 10)))
f <- function(t, flt) suppressWarnings(lake_read(t, columns = "a", filter = flt)); sh("wrapper f(tbl, a > 100), no global a", f(tbl, a > 100))
a <- 5; sh("wrapper f(tbl, a > 100), global a <- 5", f(tbl, a > 100)); sh("wrapper f(tbl, a < 100), global a <- 5 (TRUE)", f(tbl, a < 100)); rm(a)
g <- function(t, lim) suppressWarnings(lake_read(t, columns = "a", filter = a > lim)); sh("local value in function", g(tbl, 100))
h <- function(t) { a_min <- 100; (function() suppressWarnings(lake_read(t, columns = "a", filter = a > a_min)))() }; sh("value from enclosing closure", h(tbl))
sh("do.call with quoted filter", do.call(lake_read, list(tbl, columns = "a", filter = quote(a > 100))))
q <- quote(a > 100); sh("filter = q (quoted)", R(filter = q)); sh("eval(bquote())", eval(bquote(R(filter = .(q)))))
sh("filter = (a > 100) via lapply", unlist(lapply(c(100, 110), function(v) nrow(R(filter = a > v)))))
sh("filter = NULL", nrow(R(filter = NULL))); n <- NULL; sh("filter = n (NULL variable)", nrow(try1(R(filter = n))))
sh("filter missing arg", nrow(R(filter = )))
sh("filter = ~ a > 100", R(filter = ~ a > 100)); sh("filter string", R(filter = "a > 100")); sh("filter = 1", R(filter = 1)); sh("filter = c(TRUE,FALSE)", R(filter = c(TRUE, FALSE)))
ab <- 1000; sh("column ab shadows variable ab", R(filter = a > ab))
sh("a > tbl (non-vector value)", R(filter = a > tbl)); sh("value function", R(filter = a > mean)); sh("a > environment()", R(filter = a > environment()))
sh("lst$a value", { lst <- list(a = 100, z = 100); R(filter = a > lst$z) }); sh("lst$a value named like column", R(filter = a > lst$a)); sh("lst[['a']]", R(filter = a > lst[["a"]]))
sh("value uses function(a)", R(filter = a %in% sapply(c(100, 110), function(a) a))); sh("value uses function(z)", R(filter = a %in% sapply(c(100, 110), function(z) z)))
sh("with(lst, ...)", R(filter = a > with(lst, z))); sh("local({})", R(filter = a > local({ zz <- 100; zz })))
sh("side effects evaluated once", { cnt <- 0; bump <- function() { cnt <<- cnt + 1; 0 }; R(filter = a > bump() & ab > bump()); cnt })
sh("column named like base fn: `if` > 11", R(filter = `if` > 11)); T <- 0; sh("b == T with T <- 0", R(filter = b == T)); rm(T)
sh("string col == POSIXct UTC", nrow(lake_read(tbl, columns = "s", filter = s == as.POSIXct("2024-01-31 12:00:00", tz = "UTC"))))
sh("matrix value", R(filter = a == matrix(100))); sh("array %in%", R(filter = a %in% matrix(c(100, 110), 1))); sh("ts value", R(filter = a == ts(100)))
sh("value with class 'foo'", R(filter = a == structure(100, class = "foo"))); sh("difftime", R(filter = a == as.difftime(100, units = "secs"))); sh("complex", R(filter = a == 100+0i)); sh("raw", R(filter = a == as.raw(10)))
sh("hexmode", R(filter = a == as.hexmode(100))); sh("numeric_version", R(filter = a == numeric_version("100"))); sh("octmode", R(filter = a %in% as.octmode(c(8, 64))))
sh("f64 == difftime", lake_read(tbl, columns = "a", filter = f64 == as.difftime(0.1, units = "mins"))); sh("s == raw", lake_read(tbl, columns = "a", filter = s == as.raw(97))); sh("s == complex", lake_read(tbl, columns = "a", filter = s == 1i)); sh("d == difftime", lake_read(tbl, columns = "a", filter = d > as.difftime(19000, units = "days")))
sh("s == numeric_version", lake_read(tbl, columns = "a", filter = s == numeric_version("1.2")))
